REPLACE INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(24860, 'ruRU', 'Прибыльное сохранение', 'Соберите 12 артефактов ночных эльфов.', 'Знаете, наги - это мутировавшие и более симпатичные ночные эльфы, они же кальдорай. Не спрашивайте, это долгая история.$B$BВ общем, уверен, вы сможете «раздобыть» пару артефактов, пока бродите по этим руинам. Вы же понимаете, о чем я?$B$BМы обязаны сохранить их в домах богатых коллекционеров по всему миру! Верно?', '', '', '', '', '', 'Вернитесь к Эйсу в Руины Вашж''елана на Затерянных островах.', 0),
(24935, 'ruRU', 'Тело и душа', 'Уничтожьте душу Янгви.$B$BЕсли вы вдруг потеряете тело Янгви, спросите у Иззи, не нашла ли она его.', 'В этой деревне действует мощная и злая магия. Янгви был крепким орешком. Пожалуй, даже слишком крепким.$B$BЕсли оттащить его тело к большому синему костру и бросить в огонь, его душа освободится. Уничтожив ее, мы раз и навсегда разберемся с вождем умлотов и положим конец нападениям на Городок в коробке.', '', '', '', '', '', 'Вернитесь к Иззи в деревню умлотов на Затерянных островах.', 0),
(24936, 'ruRU', 'Тело и душа', 'Уничтожьте душу Янгви.$B$BЕсли вы вдруг потеряете тело Янгви, спросите у Иззи, не нашла ли она его.', 'В этой деревне действует мощная и злая магия, $n. Янгви был крепким орешком. Пожалуй, даже слишком крепким.$B$BЕсли оттащить его тело к большому синему костру и бросить в огонь, его душа освободится. Уничтожив ее, мы раз и навсегда разберемся с вождем умлотов и положим конец нападениям на Городок в коробке.', '', '', '', '', '', 'Вернитесь к Иззи в деревню умлотов на Затерянных островах.', 0),
(25225, 'ruRU', 'Замена масла', 'Соберите 6 бутылок масла Каджаро класса 0W.', 'Смазка в этих измельчителях никуда не годится. Нам нужно старое доброе масло Каджаро класса 0W!$B$BЗнаете, у кого такое масло? У маслоботов КТК! А знаете, где их найти? На нефтяной платформе КТК на северо-западе!', '', '', '', '', '', 'Вернитесь к тренеру Кроссчеку на лесопилку Трюмных Вод на Затерянных островах.', 0),
(25231, 'ruRU', 'Накипь южных морей', 'Убейте 6 наемников Южных морей.', 'Прямо сейчас Аггра и Килаг штурмуют доки, чтобы расчистить путь Траллу для схватки с торговым принцем. По плану вы должны помочь в этой атаке, но сначала нужно позаботиться о том, чтобы наемники Южных морей Галливикса не пришли ему на подмогу.$B$BСпуститесь в Рабские ямы и не дайте им этого сделать!', '', '', '', '', '', 'Вернитесь к Чогу в Рабские ямы на Затерянных островах.', 0),
(28606, 'ruRU', 'Ключи от хот-рода', '', '', '', '', '', '', '', '', 0);
